#include <cctype>
#include <iostream>
#include <string>
using namespace std;

string kichik(string s) {
    for (char& c : s) c = (char)tolower((unsigned char)c);
    return s;
}

bool oxirida(const string& s, const string& dum) {
    return s.size() >= dum.size() && s.compare(s.size() - dum.size(), dum.size(), dum) == 0;
}

string soha(const string& nom) {
    size_t oxirgi = nom.rfind('.');
    if (oxirgi == string::npos) return nom;
    size_t oldi = nom.rfind('.', oxirgi - 1);
    if (oldi == string::npos) return nom;
    return nom.substr(oldi + 1);
}

int main() {
    string t, nom;
    cin >> t;
    t = kichik(t);
    string dum = "." + t;
    while (cin >> nom) {
        string k = kichik(nom);
        if (k == t || oxirida(k, dum)) cout << "ok" << endl;
        else cout << soha(nom) << endl;
    }
    return 0;
}
